ALTER TABLE public.visitas ADD COLUMN es_prueba boolean NOT NULL DEFAULT false;
ALTER TABLE public.usuario_vista ADD COLUMN patrocinador_prueba uuid REFERENCES public.patrocinadores(id);
ALTER TABLE public.registro_permisos ADD COLUMN patrocinador_id uuid REFERENCES public.patrocinadores(id);
CREATE FUNCTION public.negocio_prueba_actual() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT patrocinador_prueba FROM public.usuario_vista WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id','') AND public.is_super_admin() $$;
REVOKE ALL ON FUNCTION public.negocio_prueba_actual() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.negocio_prueba_actual() TO authenticated;
CREATE FUNCTION public.acceder_como_negocio(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.patrocinadores WHERE id=p_id AND activo) THEN RAISE EXCEPTION 'Negocio no disponible'; END IF; UPDATE public.usuario_vista SET patrocinador_prueba=p_id WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id',''); IF NOT FOUND THEN RAISE EXCEPTION 'Selecciona una vista'; END IF; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo,patrocinador_id) VALUES(auth.uid(),auth.uid(),'acceder_como_negocio','Acceso de prueba',p_id); END $$;
CREATE FUNCTION public.salir_negocio_prueba() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; UPDATE public.usuario_vista SET patrocinador_prueba=NULL WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id',''); END $$;
CREATE FUNCTION public.guardar_visita_prueba(p_negocio uuid,p_socio uuid,p_origen text,p_tipo text,p_gasto text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN IF NOT public.is_super_admin() OR p_negocio IS DISTINCT FROM public.negocio_prueba_actual() THEN RAISE EXCEPTION 'Solo Super admin en acceso de prueba'; END IF; IF p_tipo NOT IN ('nueva','ya_era_clienta') OR p_origen NOT IN ('numero','qr','sin_carnet') OR (p_gasto IS NOT NULL AND p_gasto NOT IN ('lt20','20_50','50_100','gt100')) THEN RAISE EXCEPTION 'Datos no válidos'; END IF; PERFORM set_config('club.test_write','yes',true); INSERT INTO public.visitas(patrocinador_id,socio_id,origen,tipo_cliente,tramo_gasto,es_prueba) VALUES(p_negocio,p_socio,p_origen,p_tipo,p_gasto,true) RETURNING id INTO n; RETURN n; END $$;
CREATE FUNCTION public.borrar_visitas_prueba(p_negocio uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; PERFORM set_config('club.test_write','yes',true); DELETE FROM public.visitas WHERE patrocinador_id=p_negocio AND es_prueba; END $$;
CREATE FUNCTION public.anular_visita_prueba(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; PERFORM set_config('club.test_write','yes',true); UPDATE public.visitas SET anulada=true WHERE id=p_id AND es_prueba AND patrocinador_id=public.negocio_prueba_actual() AND fecha_hora>=now()-interval '10 minutes'; IF NOT FOUND THEN RAISE EXCEPTION 'Visita no disponible'; END IF; END $$;
CREATE FUNCTION public.proteger_visitas_prueba() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN IF OLD.es_prueba AND (NOT public.is_super_admin() OR current_setting('club.test_write',true) IS DISTINCT FROM 'yes') AND auth.role()='authenticated' THEN RAISE EXCEPTION 'Usa la función de prueba'; END IF; RETURN OLD; END IF; IF TG_OP='UPDATE' AND OLD.es_prueba IS DISTINCT FROM NEW.es_prueba THEN RAISE EXCEPTION 'No se puede cambiar el tipo de visita'; END IF; IF auth.role()='authenticated' AND (NEW.es_prueba OR public.negocio_prueba_actual() IS NOT NULL) THEN IF NOT public.is_super_admin() OR current_setting('club.test_write',true) IS DISTINCT FROM 'yes' OR NOT NEW.es_prueba THEN RAISE EXCEPTION 'Usa la función de prueba'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER visitas_prueba_guard BEFORE INSERT OR UPDATE OR DELETE ON public.visitas FOR EACH ROW EXECUTE FUNCTION public.proteger_visitas_prueba();
DROP INDEX public.visitas_una_al_dia;
CREATE UNIQUE INDEX visitas_una_al_dia ON public.visitas(socio_id,patrocinador_id,fecha,es_prueba) WHERE NOT anulada AND socio_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.validar_visita() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.socio_id IS NOT NULL THEN PERFORM 1 FROM public.socios WHERE id=NEW.socio_id AND estado='activa' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Socio no activo'; END IF; END IF; NEW.verificada:=NEW.socio_id IS NOT NULL; NEW.repite_via_club:=EXISTS(SELECT 1 FROM public.visitas v WHERE v.socio_id=NEW.socio_id AND v.patrocinador_id=NEW.patrocinador_id AND v.es_prueba=NEW.es_prueba AND NOT v.anulada AND v.fecha_hora<NEW.fecha_hora); IF NEW.socio_id IS NULL THEN NEW.origen:='sin_carnet'; END IF; RETURN NEW; END $$;
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.stats_patrocinador(uuid,text)'::regprocedure); def:=replace(def,'public.stats_patrocinador(p_patrocinador_id uuid, p_periodo text)','public.stats_negocio_datos(p_patrocinador_id uuid, p_periodo text, p_incluir_prueba boolean)'); def:=replace(def,'BEGIN IF NOT public.has_club_role','BEGIN IF p_incluir_prueba AND (NOT public.is_super_admin() OR p_patrocinador_id IS DISTINCT FROM public.negocio_prueba_actual()) THEN RAISE EXCEPTION ''Solo Super admin en acceso de prueba''; END IF; IF NOT public.has_club_role'); def:=replace(def,'AND NOT anulada','AND (p_incluir_prueba OR NOT es_prueba) AND NOT anulada'); def:=replace(def,'AND NOT v.anulada','AND (p_incluir_prueba OR NOT v.es_prueba) AND NOT v.anulada'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.stats_patrocinador(p_patrocinador_id uuid,p_periodo text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.stats_negocio_datos(p_patrocinador_id,p_periodo,false) $$;
CREATE FUNCTION public.stats_negocio_prueba(p_patrocinador_id uuid,p_periodo text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.stats_negocio_datos(p_patrocinador_id,p_periodo,true) $$;
REVOKE ALL ON FUNCTION public.stats_negocio_datos(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.acceder_como_negocio(uuid),public.salir_negocio_prueba(),public.guardar_visita_prueba(uuid,uuid,text,text,text),public.borrar_visitas_prueba(uuid),public.anular_visita_prueba(uuid),public.stats_negocio_prueba(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.acceder_como_negocio(uuid),public.salir_negocio_prueba(),public.guardar_visita_prueba(uuid,uuid,text,text,text),public.borrar_visitas_prueba(uuid),public.anular_visita_prueba(uuid),public.stats_negocio_prueba(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.identificar_socio(p_numero bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.socios; n uuid:=coalesce(public.negocio_prueba_actual(),public.mi_patrocinador()); prueba boolean:=public.negocio_prueba_actual() IS NOT NULL; BEGIN IF n IS NULL AND NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; SELECT * INTO s FROM public.socios WHERE numero_socio=p_numero AND estado='activa'; IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('id',s.id,'nombre',s.nombre,'numeroSocio',s.numero_socio,'repite',EXISTS(SELECT 1 FROM public.visitas WHERE socio_id=s.id AND patrocinador_id=n AND es_prueba=prueba AND NOT anulada),'yaHoy',EXISTS(SELECT 1 FROM public.visitas WHERE socio_id=s.id AND patrocinador_id=n AND es_prueba=prueba AND fecha=(now() AT TIME ZONE 'Europe/Madrid')::date AND NOT anulada)); END $$;